<script setup lang="ts">
import {reactive,ref} from 'vue';import type {RequestFn} from './media';
const props=defineProps<{request:RequestFn,user:Record<string,any>}>();const emit=defineEmits<{update:[user:Record<string,any>],signedOut:[message:string]}>();
const form=reactive({name:props.user.name,email:props.user.email,current_password:''}),password=reactive({current_password:'',password:'',password_confirm:''});const busy=ref(false),error=ref(''),notice=ref('');
async function submit(kind:'profile'|'password'){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{if(kind==='password'&&password.password!==password.password_confirm)throw new Error('两次输入的密码不一致');const d=await props.request('me/'+kind,'PUT',kind==='profile'?form:password);notice.value=d.message;if(kind==='profile'){emit('update',d.user);form.current_password=''}else emit('signedOut',d.message)}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
</script>
<template><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div><section class="panel"><h3>个人资料</h3><form @submit.prevent="submit('profile')"><div class="fields"><label>昵称<input v-model="form.name" required maxlength="80" autocomplete="nickname"></label><label>登录邮箱<input v-model="form.email" required type="email" autocomplete="email"></label><label v-if="form.email!==user.email">当前密码<input v-model="form.current_password" type="password" required autocomplete="current-password"><small>新邮箱验证成功前，原邮箱继续有效。验证后需重新登录。</small></label></div><button class="primary" :disabled="busy">保存个人资料</button></form></section><section class="panel"><h3>修改密码</h3><form @submit.prevent="submit('password')"><div class="fields"><label>当前密码<input v-model="password.current_password" type="password" required autocomplete="current-password"></label><label>新密码<input v-model="password.password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label>再次输入新密码<input v-model="password.password_confirm" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label></div><p v-if="password.password_confirm&&password.password!==password.password_confirm" class="alert error">两次输入的密码不一致</p><p class="muted">密码至少 12 个字符；保存后注销此账户的所有登录会话。</p><button class="primary" :disabled="busy||password.password!==password.password_confirm">修改密码并重新登录</button></form></section></template>
